create extension if not exists pgcrypto;
create table if not exists public.finance_accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,account_type text not null default 'cash' check(type in ('cash','bank','ewallet','investment','credit','other')),opening_balance numeric(16,2) not null default 0,currency text not null default 'IDR',created_at timestamptz not null default now());
create table if not exists public.finance_categories(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,kind text not null check(kind in ('income','expense')),icon text not null default '•',created_at timestamptz not null default now());
create table if not exists public.finance_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.finance_accounts(id) on delete restrict,to_account_id uuid references public.finance_accounts(id) on delete restrict,category_id uuid references public.finance_categories(id) on delete set null,kind text not null check(kind in ('income','expense','transfer')),title text not null,amount numeric(16,2) not null check(amount>0),transaction_date date not null default current_date,note text,created_at timestamptz not null default now());
create table if not exists public.finance_budgets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category_id uuid references public.finance_categories(id) on delete cascade,month date not null,amount numeric(16,2) not null check(amount>=0),created_at timestamptz not null default now(),unique(user_id,category_id,month));
create table if not exists public.finance_settings(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.finance_accounts enable row level security; alter table public.finance_categories enable row level security; alter table public.finance_transactions enable row level security; alter table public.finance_budgets enable row level security; alter table public.finance_settings enable row level security;
drop policy if exists accounts_owner_all on public.finance_accounts; create policy accounts_owner_all on public.finance_accounts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
drop policy if exists categories_read on public.finance_categories; create policy categories_read on public.finance_categories for select to authenticated using (user_id is null or (select auth.uid())=user_id);
drop policy if exists categories_owner_insert on public.finance_categories; create policy categories_owner_insert on public.finance_categories for insert to authenticated with check ((select auth.uid())=user_id);
drop policy if exists categories_owner_update on public.finance_categories; create policy categories_owner_update on public.finance_categories for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
drop policy if exists categories_owner_delete on public.finance_categories; create policy categories_owner_delete on public.finance_categories for delete to authenticated using ((select auth.uid())=user_id);
drop policy if exists transactions_owner_all on public.finance_transactions; create policy transactions_owner_all on public.finance_transactions for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id and exists(select 1 from public.finance_accounts a where a.id=account_id and a.user_id=(select auth.uid())) and (to_account_id is null or exists(select 1 from public.finance_accounts a where a.id=to_account_id and a.user_id=(select auth.uid()))) and (category_id is null or exists(select 1 from public.finance_categories c where c.id=category_id and (c.user_id=(select auth.uid()) or c.user_id is null))));
drop policy if exists budgets_owner_all on public.finance_budgets; create policy budgets_owner_all on public.finance_budgets for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
drop policy if exists settings_owner_all on public.finance_settings; create policy settings_owner_all on public.finance_settings for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create index if not exists finance_transactions_user_date_idx on public.finance_transactions(user_id,transaction_date desc);
create index if not exists finance_transactions_account_idx on public.finance_transactions(account_id);
create index if not exists finance_accounts_user_idx on public.finance_accounts(user_id);
create index if not exists finance_categories_user_idx on public.finance_categories(user_id);
insert into public.finance_categories(user_id,name,kind,icon) values (null,'Gaji','income','＋'),(null,'Bonus','income','✦'),(null,'Makanan','expense','⌁'),(null,'Transportasi','expense','↗'),(null,'Belanja','expense','◇'),(null,'Tagihan','expense','▤'),(null,'Kesehatan','expense','＋'),(null,'Hiburan','expense','♫'),(null,'Pendidikan','expense','▧'),(null,'Lainnya','expense','•') on conflict do nothing;